CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE INDEX "Course_title_trgm" ON "Course" USING gin ("title" gin_trgm_ops);
CREATE INDEX "Course_subject_trgm" ON "Course" USING gin ("subject" gin_trgm_ops);
CREATE INDEX "User_name_trgm" ON "User" USING gin ("name" gin_trgm_ops);
CREATE UNIQUE INDEX "Payment_one_unfinished" ON "Payment" ("enrollmentId") WHERE "status" IN ('pending', 'awaiting_review');
ALTER TABLE "Course" ADD CONSTRAINT "Course_price_positive" CHECK ("monthlyPriceMinor" > 0 AND "currency" = 'KZT');
ALTER TABLE "Payment" ADD CONSTRAINT "Payment_money_valid" CHECK ("amountMinor" > 0 AND "commissionBps" BETWEEN 0 AND 10000 AND "currency" = 'KZT');
ALTER TABLE "Payout" ADD CONSTRAINT "Payout_balanced" CHECK ("grossMinor" = "commissionMinor" + "netMinor" AND "netMinor" >= 0 AND "commissionMinor" >= 0);
ALTER TABLE "Material" ADD CONSTRAINT "Material_exactly_one_source" CHECK (("kind"='file' AND "fileAssetId" IS NOT NULL AND "url" IS NULL) OR ("kind"='link' AND "url" IS NOT NULL AND "fileAssetId" IS NULL));
ALTER TABLE "Question" ADD CONSTRAINT "Question_positive_points" CHECK ("points" > 0);
ALTER TABLE "FileAsset" ADD CONSTRAINT "FileAsset_size" CHECK ("sizeBytes" > 0 AND "sizeBytes" <= 20971520);
